def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    h = [float(b["h"]) for b in bars]
    l = [float(b["l"]) for b in bars]

    # 5-bar mean range of the bars IMMEDIATELY BEFORE each bar -- the
    # "narrow spread" yardstick, which must not include the bar it judges.
    rng = [h[i] - l[i] for i in range(n)]
    prior = [None] * n
    run = 0.0
    for i in range(n):
        if i >= 1:
            run += rng[i - 1]
        if i >= 6:
            run -= rng[i - 6]
        if i >= 5:
            prior[i] = run / 5.0
    ctx.prior5 = ctx.series(prior, "mean_range_5_prior")
    ctx.sma = ctx.indicator("sma", period=int(ctx.p.sma_n))


def _quiet_bar(ctx, s, want_down):
    """Is bar s a no-supply (want_down) / no-demand (not want_down) bar?"""
    c, o, h, l, v = ctx.c, ctx.o, ctx.h, ctx.l, ctx.v
    cs, ps = c[s], c[s - 1]
    if cs is None or ps is None:
        return False
    if want_down and not (cs < ps):
        return False
    if (not want_down) and not (cs > ps):
        return False

    m = ctx.prior5[s]
    if m is None or m <= 0:
        return False
    rng = h[s] - l[s]
    if rng > ctx.p.spread_mult * m:          # (b) narrow spread
        return False

    k = int(ctx.p.vol_back)                  # (c) below the last k bars' volume
    vs = v[s]
    for j in range(1, k + 1):
        if s - j < 0 or not (vs < v[s - j]):
            return False

    if rng <= 0:                             # a doji bar has no close position
        return False
    pos = (c[s] - l[s]) / rng                # (d) close position within the bar
    if want_down and pos < ctx.p.close_pos:
        return False
    if (not want_down) and pos > 1.0 - ctx.p.close_pos:
        return False

    sm = ctx.sma[s]                          # (e) context
    if sm is None:
        return False
    if want_down and not (cs > sm):
        return False
    if (not want_down) and not (cs < sm):
        return False
    return True


def signal(ctx, i):
    """i is the CONFIRMATION bar; the signal bar S is the one before it."""
    s = i - 1
    if s < 8:
        return 0
    if _quiet_bar(ctx, s, True):
        # confirmation: closes above the signal bar's high on rising volume
        if ctx.c[i] > ctx.h[s] and ctx.v[i] > ctx.v[s]:
            return 1
    if _quiet_bar(ctx, s, False):
        if ctx.c[i] < ctx.l[s] and ctx.v[i] > ctx.v[s]:
            return -1
    return 0
